import React from "react";

import {createBrowserRouter, RouterProvider, redirect} from "react-router-dom";
import ErrorPage from "./ErrorPage";
import LoginView from "../views/Login/LoginView";
import RegistrationView from "../views/Login/RegistrationView";
import Dashboard from "../views/Dashboards/Dashboard";
import HomeView from "../views/HomeView";
import SubscriptionView from "../views/Subscription/SubscriptionView";
import SubscriptionViewPart from "../views/Subscription/SubscriptionViewPart";
import HomeMainView from "../views/HomeMain/HomeMainView";
import ClientCatalogView from "../views/ClientCatalog/ClientCatalogView";
import UserCatalogView from "../views/UserCatalog/UserCatalogView";
import SubscriptionSuccess from "../views/Subscription/SubscriptionSuccess";
import MyBusiness from "../views/MyBusiness/MyBusiness";
import AnalyticsView from "../views/Analytics/AnalyticsView";
import MyTicketsView from "../views/MyTickets/MyTicketsView";
import ShopView from "../views/Shop/ShopView";
import SettingsPlatform from "../views/MyTabsConfiguration/SettingsPlatform";
import EventsView from "../views/Events/EventsView";
import EventCreate from "../views/Events/EventCreate";
import EventCreateNew from "../views/Events/EventCreateNew";
import EventEdit from "../views/Events/EventEdit";
import EventEditNew from "../views/Events/EventEditNew";
import PasswordRecovery from "../views/Login/PasswordRecovery";
import ChangePasswordView from "../views/Login/ChangePasswordView";
import DeleteAccountView from "../views/Login/DeleteAccountView";
import AdminPortal from "../views/Admin/AdminPortal";
import TicketPurchase from "../views/Tickets/TicketPurchase";
import TicketSuccess from "../views/Tickets/TicketSuccess";
import TicketCancel from "../views/Tickets/TicketCancel";
import BusinessRedirect from "../views/BusinessRedirect";
import OrganizationList from "../views/Organization/OrganizationList";
import OrganizationDashboard from "../views/Organization/OrganizationDashboard";
import CreateOrganization from "../views/Organization/CreateOrganization";
import ServiceLanding from "../views/ServiceLanding/ServiceLanding";
import MarketIntelligence from "../views/ServiceLanding/MarketIntelligence";
import JumpPage from "../views/JumpPage/JumpPage";

const routerHandler = (isIntern, allowPass = false) => {
  const _idToken = localStorage.getItem("idToken");

  if (!_idToken && isIntern) {
    return redirect("/login");
  } else if (_idToken && !isIntern) {
    if(allowPass) {
      return false
    }
    return redirect("/admin/home");
  }
  return false;
};
const router = createBrowserRouter([
  {
    errorElement: <ErrorPage />,
    children: [
       {
        path: "/",
        loader: () => {
          const _idToken = localStorage.getItem("idToken");
          if (_idToken) {
            return redirect("/admin/home");
          } else {
            return redirect("/login");
          }
        },
      },
      {
        path: "login",
        element: <LoginView />,
        loader: () => {
          // Check if there's a returnUrl parameter - if so, allow the login page to handle the redirect
          const params = new URLSearchParams(window.location.search);
          const hasReturnUrl = params.has('returnUrl');
          return routerHandler(false, hasReturnUrl);
        },
      },
      {
        path: "password-recovery",
        element: <PasswordRecovery />,
        loader: () => routerHandler(false, true),
      },
      {
        path: "change-password",
        element: <ChangePasswordView />,
        loader: () => routerHandler(true, true),
      },
      {
        path: "delete-account",
        element: <DeleteAccountView />,
        loader: () => routerHandler(false),
      },
      {
        path: "register",
        element: <RegistrationView />,
        loader: () => routerHandler(false),
      },
      {
        path: "subscription",
        element: <SubscriptionView />,
        // loader: () => routerHandler(true),
      },
      {
        path: "subpart",
        element: <SubscriptionViewPart />,
        // loader: () => routerHandler(true),
      },
      {
        path: "success",
        element: <SubscriptionSuccess />,
        //   loader: async ({ params }) => {
        //     console.log(params.sessionId);
        // },
      },
      {
        path: "success/session_id=:sessionId",
        element: <SubscriptionSuccess />,
        //   loader: async ({ params }) => {
        //     console.log(params.sessionId);
        // },
      },
      {
        path: "user/:userId",
        Component: () => {
          window.location.href = 'https://www.mytabs.app';
          return null;
        }
      },
      {
        path: "business/:businessId",
        element: <BusinessRedirect />,
        loader: ({ params }) => {
          return params.businessId;
        }
      },
      {
        path: "admin-portal",
        element: <AdminPortal />,
      },
      {
        path: "tickets/:eventId",
        element: <TicketPurchase />,
      },
      {
        path: "tickets/success",
        element: <TicketSuccess />,
      },
      {
        path: "tickets/cancel",
        element: <TicketCancel />,
      },
      {
        path: "b/:code",
        element: <JumpPage />,
      },
      {
        path: "m/:code",
        element: <JumpPage />,
      },
      {
        path: "e/:code",
        element: <JumpPage />,
      },
      {
        path: "o/:code",
        element: <JumpPage />,
      },
      {
        path: "/admin",
        element: <HomeView />,
        loader: () => routerHandler(true),
        children: [
          {
            path: "dashboards",
            element: <Dashboard />,
            loader: () => routerHandler(true),
          },
          {
            path: "home",
            element: <HomeMainView />,
            loader: () => routerHandler(true),
          },
          {
            path: "client-catalog",
            element: <ClientCatalogView />,
            loader: () => routerHandler(true),
          },
          {
            path: "user-catalog",
            element: <UserCatalogView />,
            loader: () => routerHandler(true),
          },
          {
            path: "my-business",
            element: <MyBusiness />,
            loader: () => routerHandler(true),
          },
          {
            path: "my-business/:businessId",
            element: <MyBusiness />,
            loader: () => routerHandler(true),
          },
          {
            path: "my-events",
            element: <EventsView />,
            loader: () => routerHandler(true),
          },
          {
            path: "my-events/create",
            element: <EventCreateNew />,
            loader: () => routerHandler(true),
          },
          {
            path: "my-events/create-old",
            element: <EventCreate />,
            loader: () => routerHandler(true),
          },
          {
            path: "my-events/:eventId",
            element: <EventEditNew />,
            loader: () => routerHandler(true),
          },
          {
            path: "analytics",
            element: <AnalyticsView />,
            loader: () => routerHandler(true),
          },
          {
            path: "my-tickets",
            element: <MyTicketsView />,
            loader: () => routerHandler(true),
          },
          {
            path: "shop",
            element: <ShopView />,
            loader: () => routerHandler(true),
          },
          {
            path: "configuration",
            element: <SettingsPlatform />,
            loader: () => routerHandler(true),
          },
          {
            path: "admin-portal",
            element: <AdminPortal />,
            loader: () => routerHandler(true),
          },
          {
            path: "organization",
            element: <OrganizationList />,
            loader: () => routerHandler(true),
          },
          {
            path: "organization/create",
            element: <CreateOrganization />,
            loader: () => routerHandler(true),
          },
          {
            path: "organization/:id",
            element: <OrganizationDashboard />,
            loader: () => routerHandler(true),
          },
          {
            path: "service/market-intelligence",
            element: <MarketIntelligence />,
            loader: () => routerHandler(true),
          },
          {
            path: "service/:serviceId",
            element: <ServiceLanding />,
            loader: () => routerHandler(true),
          },
        ],
      },
    ],
  },
]);

const Router = () => {
  return <RouterProvider router={router} />;
};

export default Router;
